+
+impl Default for AdaptiveTrochParams {
+    fn default() -> Self {
+        Self {
+            max_engagement: DEFAULT_MAX_ENGAGEMENT,
+            ret: None,
+            return_feed: None,
+            loop_width: None,
+        }
+    }
+}
